import sys

def main():
    s = sys.stdin.read().strip()
    n = len(s)
    best_sub = ""
    best_count = 0

    for i in range(n):
        for j in range(i + 1, n + 1):
            sub = s[i:j]
            count = 0
            k = 0
            while True:
                pos = s.find(sub, k)
                if pos == -1:
                    break
                count += 1
                k = pos + 1

            if count > best_count:
                best_count = count
                best_sub = sub
            elif count == best_count:
                if len(sub) > len(best_sub):
                    best_sub = sub
                elif len(sub) == len(best_sub):
                    if sub > best_sub:
                        best_sub = sub

    print(best_sub)

if __name__ == "__main__":
    main()
